-- Atlas Money Collection Kernel v1 — source-domain write membrane fence.
-- Reviewed migration-source SQL only; not a generated Supabase migration.
--
-- Production audit at this boundary proves:
-- - only record_flower_sale_core_v1/v2 insert flower_sale_orders;
-- - only submit_public_household_registration_v1 inserts community_registrations.
--
-- SECURITY DEFINER governed commands execute as their owning database role and
-- therefore do not require service_role direct table mutation privileges.
-- Remove those raw mutation paths so a service-role application cannot bypass
-- the source-domain command and silently omit the Money postcondition.

revoke insert,update,delete,truncate
  on atlas.flower_sale_orders
  from service_role;
revoke insert,update,delete,truncate
  on atlas.flower_sale_order_lines
  from service_role;

revoke insert,update,delete,truncate
  on atlas.community_registrations
  from service_role;
revoke insert,update,delete,truncate
  on atlas.community_registration_participants
  from service_role;

-- Keep existing SELECT/REFERENCES privileges unless a separate read-custody
-- change requires tightening them. This tranche governs mutation authority only.

-- Atlas Money Collection Kernel v1 — retire obsolete source coverage reader.
-- Reviewed migration-source SQL only; not a generated Supabase migration.
--
-- Assemble after atlas-money-collection-kernel-v1-source-consistency.sql, which
-- installs the source-currency-aware overload and rebinds both current domain
-- readers. The seven-argument draft reader cannot verify source currency and
-- must not remain as a competing internal authority.

drop function atlas.money_source_coverage_state_core_v1(
  uuid,text,text,text,text,timestamptz,numeric
);

-- Activate both globally installed source adapters only after every governed
-- writer replacement/fence above is installed. Use one actual post-lock wall
-- clock value so legacy writers that completed while this transaction waited
-- for the cutover locks are never misclassified as kernel-covered.
do $$
declare
  v_cutover_at timestamptz := clock_timestamp();
begin
  perform atlas.activate_money_source_adapter_coverage_core_v1(
    'community_registration',
    'registration',
    'participation_fee',
    'community_registration_money_v1',
    v_cutover_at,
    '20260901161304_atlas_money_collection_kernel_v1',
    null,
    '{"cleanCutover":true}'::jsonb
  );

  perform atlas.activate_money_source_adapter_coverage_core_v1(
    'flower_commerce',
    'flower_sale_order',
    'sale_total',
